  1	const OPTION_DEFINITIONS = [
  2	  { flag: '--a', key: 'a', metavar: 'A' },
  3	  { flag: '--b', key: 'b', metavar: 'B' },
  4	  { flag: '--c', key: 'c', metavar: 'C' },
  5	];
  6	
  7	const OPTION_BY_FLAG = new Map(
  8	  OPTION_DEFINITIONS.map((definition) => [definition.flag, definition]),
  9	);
 10	
 11	function buildUsageText(progName) {
 12	  const optionText = OPTION_DEFINITIONS.map(
 13	    (definition) => `${definition.flag} ${definition.metavar}`,
 14	  ).join(' ');
 15	
 16	  return `usage: ${progName} [-h] ${optionText}\n`;
 17	}
 18	
 19	export function buildHelpText(progName) {
 20	  return (
 21	    `${buildUsageText(progName)}\n` +
 22	    'options:\n' +
 23	    '  -h, --help  show this help message and exit\n' +
 24	    '  --a A\n' +
 25	    '  --b B\n' +
 26	    '  --c C\n'
 27	  );
 28	}
