 30	export function getProgramName(scriptPath = process.argv[1]) {
 31	  if (!scriptPath) {
 32	    return 'test6.mjs';
 33	  }
 34	
 35	  const normalizedPath = scriptPath.replace(/\\/g, '/');
 36	  const lastSlashIndex = normalizedPath.lastIndexOf('/');
 37	  return lastSlashIndex === -1 ? normalizedPath : normalizedPath.slice(lastSlashIndex + 1);
 38	}
 39	
 40	function splitLongOption(token) {
 41	  if (!token.startsWith('--')) {
 42	    return null;
 43	  }
 44	
 45	  const equalsIndex = token.indexOf('=');
 46	  if (equalsIndex === -1) {
 47	    return {
 48	      flag: token,
 49	      hasInlineValue: false,
 50	      inlineValue: '',
 51	    };
 52	  }
 53	
 54	  return {
 55	    flag: token.slice(0, equalsIndex),
 56	    hasInlineValue: true,
 57	    inlineValue: token.slice(equalsIndex + 1),
 58	  };
 59	}
 60	
 61	function looksLikeNegativeNumber(token) {
 62	  return /^-\d+(\.\d*)?$/.test(token) || /^-\.\d+$/.test(token);
 63	}
 64	
 65	function isMissingValueToken(token) {
 66	  return token === '--' || (token.startsWith('-') && token !== '-' && !looksLikeNegativeNumber(token));
 67	}
 68	
 69	function exitWithHelp(progName, stdout, exit) {
 70	  stdout.write(buildHelpText(progName));
 71	  exit(0);
 72	  return null;
 73	}
 74	
 75	function exitWithError(progName, message, stderr, exit) {
 76	  stderr.write(buildUsageText(progName));
 77	  stderr.write(`${progName}: error: ${message}\n`);
 78	  exit(2);
 79	  return null;
 80	}
 81	
 82	export function parseCommandLine(
 83	  argv,
 84	  {
 85	    progName = getProgramName(),
 86	    stdout = process.stdout,
 87	    stderr = process.stderr,
 88	    exit = (code) => process.exit(code),
 89	  } = {},
 90	) {
 91	  const values = {
 92	    a: undefined,
 93	    b: undefined,
 94	    c: undefined,
 95	  };
 96	  const extras = [];
 97	
 98	  for (let index = 0; index < argv.length; index += 1) {
 99	    const token = argv[index];
100	
101	    if (token === '-h' || token === '--help') {
102	      return exitWithHelp(progName, stdout, exit);
103	    }
104	
105	    if (token === '--') {
106	      extras.push(...argv.slice(index + 1));
107	      break;
108	    }
109	
110	    const option = splitLongOption(token);
111	    if (option !== null && OPTION_BY_FLAG.has(option.flag)) {
112	      const definition = OPTION_BY_FLAG.get(option.flag);
113	
114	      if (option.hasInlineValue) {
115	        values[definition.key] = option.inlineValue;
116	        continue;
117	      }
118	
119	      const nextToken = argv[index + 1];
120	      if (nextToken === undefined || isMissingValueToken(nextToken)) {
121	        return exitWithError(progName, `argument ${option.flag}: expected one argument`, stderr, exit);
122	      }
123	
124	      values[definition.key] = nextToken;
125	      index += 1;
126	      continue;
127	    }
128	
129	    extras.push(token);
130	  }
131	
132	  const missingFlags = OPTION_DEFINITIONS.filter(
133	    (definition) => values[definition.key] === undefined,
134	  ).map((definition) => definition.flag);
135	
136	  if (missingFlags.length > 0) {
137	    return exitWithError(
138	      progName,
139	      `the following arguments are required: ${missingFlags.join(', ')}`,
140	      stderr,
141	      exit,
142	    );
143	  }
144	
145	  if (extras.length > 0) {
146	    return exitWithError(progName, `unrecognized arguments: ${extras.join(' ')}`, stderr, exit);
147	  }
148	
149	  return values;
150	}

