 3	export class OrderedMultiDict {
 4	  constructor() {
 5	    this._entries = [];
 6	    this._valuesByKey = new Map();
 7	    this._keyOrder = [];
 8	  }
 9	
10	  add(key, value) {
11	    if (!this._valuesByKey.has(key)) {
12	      this._valuesByKey.set(key, []);
13	      this._keyOrder.push(key);
14	    }
15	
16	    this._valuesByKey.get(key).push(value);
17	    this._entries.push([key, value]);
18	    return undefined;
19	  }
20	
21	  getlist(key) {
22	    const values = this._valuesByKey.get(key);
23	    return values ? values.slice() : [];
24	  }
25	
26	  keys() {
27	    return this._keyOrder.slice();
28	  }
29	
30	  items() {
31	    return this._keyOrder.map((key) => {
32	      const values = this._valuesByKey.get(key);
33	      return createPythonTuple(key, values[values.length - 1]);
34	    });
35	  }
36	
37	  toPythonRepr() {
38	    const entries = this._entries.map(([key, value]) => createPythonTuple(key, value));
39	    return `OrderedMultiDict(${pythonListRepr(entries)})`;
40	  }
41	}
