  1	const PYTHON_TUPLE = Symbol('python_tuple');
  2	
  3	export function createPythonTuple(...items) {
  4	  return {
  5	    [PYTHON_TUPLE]: true,
  6	    items,
  7	  };
  8	}
  9	
 10	function isPythonTuple(value) {
 11	  return Boolean(value) && value[PYTHON_TUPLE] === true;
 12	}
 13	
 14	function chooseQuote(text) {
 15	  if (text.includes("'") && !text.includes('"')) {
 16	    return '"';
 17	  }
 18	  return "'";
 19	}
 20	
 21	function isEscapedCodePoint(codePoint) {
 22	  return (
 23	    codePoint < 0x20 ||
 24	    (codePoint >= 0x7f && codePoint <= 0xa0) ||
 25	    (codePoint >= 0xd800 && codePoint <= 0xdfff)
 26	  );
 27	}
 28	
 29	function escapeCodePoint(character, quote) {
 30	  const codePoint = character.codePointAt(0);
 31	
 32	  if (character === '\\') {
 33	    return '\\\\';
 34	  }
 35	
 36	  if (character === quote) {
 37	    return `\\${quote}`;
 38	  }
 39	
 40	  if (character === '\t') {
 41	    return '\\t';
 42	  }
 43	
 44	  if (character === '\n') {
 45	    return '\\n';
 46	  }
 47	
 48	  if (character === '\r') {
 49	    return '\\r';
 50	  }
 51	
 52	  if (isEscapedCodePoint(codePoint)) {
 53	    if (codePoint <= 0xff) {
 54	      return `\\x${codePoint.toString(16).padStart(2, '0')}`;
 55	    }
 56	
 57	    if (codePoint <= 0xffff) {
 58	      return `\\u${codePoint.toString(16).padStart(4, '0')}`;
 59	    }
 60	
 61	    return `\\U${codePoint.toString(16).padStart(8, '0')}`;
 62	  }
 63	
 64	  return character;
 65	}
 66	
 67	export function pythonStringRepr(text) {
 68	  const quote = chooseQuote(text);
 69	  let body = '';
 70	
 71	  for (const character of text) {
 72	    body += escapeCodePoint(character, quote);
 73	  }
 74	
 75	  return `${quote}${body}${quote}`;
 76	}
