 78	export function pythonTupleRepr(values) {
 79	  const parts = values.map((value) => pythonRepr(value));
 80	
 81	  if (parts.length === 1) {
 82	    return `(${parts[0]},)`;
 83	  }
 84	
 85	  return `(${parts.join(', ')})`;
 86	}
 87	
 88	export function pythonListRepr(values) {
 89	  return `[${values.map((value) => pythonRepr(value)).join(', ')}]`;
 90	}
 91	
 92	export function pythonRepr(value) {
 93	  if (typeof value === 'string') {
 94	    return pythonStringRepr(value);
 95	  }
 96	
 97	  if (Array.isArray(value)) {
 98	    return pythonListRepr(value);
 99	  }
100	
101	  if (isPythonTuple(value)) {
102	    return pythonTupleRepr(value.items);
103	  }
104	
105	  if (value && typeof value.toPythonRepr === 'function') {
106	    return value.toPythonRepr();
107	  }
108	
109	  if (value === null || value === undefined) {
110	    return 'None';
111	  }
112	
113	  if (value === true) {
114	    return 'True';
115	  }
116	
117	  if (value === false) {
118	    return 'False';
119	  }
120	
121	  if (typeof value === 'number' || typeof value === 'bigint') {
122	    return String(value);
123	  }
124	
125	  throw new TypeError(`Unsupported value for pythonRepr: ${String(value)}`);
126	}

